/** M99: AndroidManifest is generated by Capacitor in CI; patch it there, not in a missing tracked android/ tree. */
import fs from "node:fs";
const path = "android/app/src/main/AndroidManifest.xml";
if (!fs.existsSync(path)) throw new Error("M99: AndroidManifest gerado não encontrado");
let xml = fs.readFileSync(path, "utf8");
const permission = 'android.permission.SCHEDULE_EXACT_ALARM';
if (!xml.includes(permission)) {
  const anchor = /<application\b/;
  if (!anchor.test(xml)) throw new Error("M99: Application ausente do AndroidManifest");
  xml = xml.replace(anchor, `<uses-permission android:name="${permission}" />\n    <application`);
  fs.writeFileSync(path, xml, "utf8");
}
if ((xml.match(/android\.permission\.SCHEDULE_EXACT_ALARM/g) || []).length !== 1) {
  throw new Error("M99: permissão de alarmes exatos duplicada");
}
if (xml.includes("android.permission.USE_FULL_SCREEN_INTENT") || xml.includes("android.permission.USE_EXACT_ALARM")) {
  throw new Error("M99: permissão invasiva não autorizada");
}
console.log("M99: SCHEDULE_EXACT_ALARM presente uma única vez; sem full-screen e sem USE_EXACT_ALARM");
